input.command:
mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'E'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
E
cat > providers.tf <<'E'
provider "aws" {
  region = var.region
}
E
cat > variables.tf <<'E'
variable "region" {
  type        = string
  description = "AWS region the state bucket is created in. The backend block in the parent configuration must use the same region."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose a name unique to your organization."
}

variable "noncurrent_version_expiration_days" {
  type        = number
  description = "Days a superseded state version is kept before it is deleted. Older versions are the rollback path for a corrupt state file."
  default     = 90
}
E
cat > main.tf <<'E'
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  # State holds every secret the configuration manages; losing the bucket by
  # accident is worse than having to remove this guard deliberately.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_expiration_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
E
cat > outputs.tf <<'E'
output "state_bucket_name" {
  description = "Name of the state bucket, for the bucket argument of the parent backend block."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key that encrypts state, for the kms_key_id argument of the parent backend block."
  value       = aws_kms_key.state.arn
}
E
cd ..
cat > backend.tf <<'E'
# Bucket and key are created by bootstrap/. Credentials come from the default
# AWS credential chain; none belong in this file. Locking uses an S3 lock
# object (use_lockfile), so no DynamoDB table is needed.
terraform {
  backend "s3" {
    bucket       = "REPLACE-WITH-STATE-BUCKET-NAME"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    kms_key_id   = "REPLACE-WITH-STATE-KMS-KEY-ARN"
    use_lockfile = true
  }
}
E
printf '.terraform/\n*.tfstate\n*.tfstate.*\n*.tfplan\ncrash.log\ncrash.*.log\n*.auto.tfvars\nterraform.tfvars\n' > .gitignore
terraform fmt -recursive -check -diff; (cd bootstrap && terraform init -backend=false -input=false >/dev/null && terraform validate); terraform init -backend=false -input=false >/dev/null && terraform validate; git status --short

